#!/usr/bin/env node
/**
 * Four.meme - token list (REST API)
 * POST /meme-api/v1/public/token/search
 *
 * Usage: fourmeme token-list [options]
 *   New: --type= --listType= --keyword= --symbol= --tag= --status= --sort= --version= --pageIndex= --pageSize=
 *   Legacy: --orderBy=Hot|TimeDesc|Time (maps to type+sort), --tokenName= (->keyword), --labels= (->tag), --listedPancake= (->status)
 * Output: JSON list of tokens.
 */

const API_BASE = 'https://four.meme/meme-api/v1';

const ORDERBY_TO_TYPE: Record<string, { type: string; sort?: string }> = {
  Hot: { type: 'HOT' },
  TimeDesc: { type: 'NEW', sort: 'DESC' },
  Time: { type: 'NEW' },
};

function parseArg(name: string, defaultValue: string): string {
  const prefix = `--${name}=`;
  for (let i = 2; i < process.argv.length; i++) {
    const arg = process.argv[i];
    if (arg.startsWith(prefix)) return arg.slice(prefix.length);
  }
  return defaultValue;
}

async function main() {
  const orderBy = parseArg('orderBy', 'Hot');
  const tokenName = parseArg('tokenName', '');
  const listedPancake = parseArg('listedPancake', 'false');
  const pageIndex = parseArg('pageIndex', '1');
  const pageSize = parseArg('pageSize', '20');
  const symbol = parseArg('symbol', '');
  const labels = parseArg('labels', '');

  // New params (override legacy when provided)
  const typeArg = parseArg('type', '');
  const listType = parseArg('listType', '');
  const keyword = parseArg('keyword', tokenName);
  const tagArg = parseArg('tag', labels);
  const statusArg = parseArg('status', '');
  const sortArg = parseArg('sort', '');
  const version = parseArg('version', '');

  const body: Record<string, string | number | string[]> = {
    pageIndex: parseInt(pageIndex, 10) || 1,
    pageSize: parseInt(pageSize, 10) || 20,
  };

  if (listType) {
    body.listType = listType;
  } else if (listedPancake === 'true') {
    body.listType = 'NOR_DEX';
  } else {
    body.listType = 'NOR';
  }

  if (typeArg) {
    body.type = typeArg;
  } else if (body.listType === 'NOR_DEX') {
    body.type = 'NEW';
    body.sort = 'DESC';
  } else if (ORDERBY_TO_TYPE[orderBy]) {
    const mapped = ORDERBY_TO_TYPE[orderBy];
    body.type = mapped.type;
    if (mapped.sort) body.sort = mapped.sort;
  } else {
    body.type = 'HOT';
  }
  if (keyword) body.keyword = keyword;
  if (symbol) body.symbol = symbol;
  if (tagArg) {
    body.tag = tagArg.split(',').map((s) => s.trim()).filter(Boolean);
  }
  if (statusArg) body.status = statusArg;
  else if (body.listType === 'NOR_DEX') body.status = 'TRADE';
  if (sortArg) body.sort = sortArg;
  else if (!body.sort) body.sort = 'DESC';
  if (version) body.version = version;

  const url = `${API_BASE}/public/token/search`;
  const res = await fetch(url, {
    method: 'POST',
    headers: {
      Accept: 'application/json',
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  });
  const data = await res.json();
  const ok = (data.code === 0 || data.code === '0') && res.ok;

  if (!ok) {
    throw new Error(`token/search failed: ${res.status} ${JSON.stringify(data)}`);
  }
  console.log(JSON.stringify(data, null, 2));
}

main().catch((e) => {
  console.error(e.message || e);
  process.exit(1);
});

#!/usr/bin/env node
/**
 * Four.meme - token rankings (REST API)
 * POST /meme-api/v1/public/token/ranking
 * Body: { type, rankingKind?, version?, symbol?, minCap?, maxCap?, minVol?, maxVol?, minHold?, maxHold?, pageSize? }
 *
 * Usage: fourmeme token-rankings <type> [options]
 *   type: NEW | PROGRESS | VOL_MIN_5 | VOL_MIN_30 | VOL_HOUR_1 | VOL_HOUR_4 | VOL_DAY_1 | VOL | LAST | HOT | CAP | DEX
 *   Legacy (mapped): Time->NEW, ProgressDesc->PROGRESS, TradingDesc->VOL_DAY_1, Hot->HOT, Graduated->DEX
 *   options: --rankingKind= --version= --symbol= --minCap= --maxCap= --minVol= --maxVol= --minHold= --maxHold= --pageSize=20
 * Output: JSON ranking list.
 */

const API_BASE = 'https://four.meme/meme-api/v1';

const VALID_TYPES = [
  'NEW',
  'PROGRESS',
  'VOL_MIN_5',
  'VOL_MIN_30',
  'VOL_HOUR_1',
  'VOL_HOUR_4',
  'VOL_DAY_1',
  'VOL',
  'LAST',
  'HOT',
  'CAP',
  'DEX',
];

const LEGACY_MAP: Record<string, string> = {
  Time: 'NEW',
  ProgressDesc: 'PROGRESS',
  TradingDesc: 'VOL_DAY_1',
  Hot: 'HOT',
  Graduated: 'DEX',
};

function parseArg(name: string, defaultValue?: string): string | undefined {
  const prefix = `--${name}=`;
  for (let i = 3; i < process.argv.length; i++) {
    const arg = process.argv[i];
    if (arg.startsWith(prefix)) return arg.slice(prefix.length);
  }
  return defaultValue;
}

function parseNumArg(name: string): number | undefined {
  const v = parseArg(name);
  if (v === undefined) return undefined;
  const n = Number(v);
  return Number.isNaN(n) ? undefined : n;
}

async function main() {
  const typeArg = process.argv[2];
  const type = typeArg ? (LEGACY_MAP[typeArg] ?? typeArg) : undefined;

  if (!type || !VALID_TYPES.includes(type)) {
    console.error('Usage: fourmeme token-rankings <type> [options]');
    console.error(
      'type: NEW | PROGRESS | VOL_MIN_5 | VOL_MIN_30 | VOL_HOUR_1 | VOL_HOUR_4 | VOL_DAY_1 | VOL | LAST | HOT | CAP | DEX'
    );
    console.error('Legacy: Time, ProgressDesc, TradingDesc, Hot, Graduated');
    console.error('options: --rankingKind= --version= --symbol= --minCap= --maxCap= --minVol= --maxVol= --minHold= --maxHold= --pageSize=20');
    process.exit(1);
  }

  const body: Record<string, string | number> = { type };

  const rankingKind = parseArg('rankingKind');
  if (rankingKind) body.rankingKind = rankingKind;

  const version = parseArg('version');
  if (version) body.version = version;

  const symbol = parseArg('symbol');
  if (symbol) body.symbol = symbol;

  const minCap = parseNumArg('minCap');
  if (minCap !== undefined) body.minCap = minCap;

  const maxCap = parseNumArg('maxCap');
  if (maxCap !== undefined) body.maxCap = maxCap;

  const minVol = parseNumArg('minVol');
  if (minVol !== undefined) body.minVol = minVol;

  const maxVol = parseNumArg('maxVol');
  if (maxVol !== undefined) body.maxVol = maxVol;

  const minHold = parseNumArg('minHold');
  if (minHold !== undefined) body.minHold = minHold;

  const maxHold = parseNumArg('maxHold');
  if (maxHold !== undefined) body.maxHold = maxHold;

  const pageSize = parseNumArg('pageSize');
  if (pageSize !== undefined) body.pageSize = pageSize;

  const url = `${API_BASE}/public/token/ranking`;
  const res = await fetch(url, {
    method: 'POST',
    headers: {
      Accept: 'application/json',
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  });
  if (!res.ok) {
    throw new Error(`token/ranking failed: ${res.status} ${await res.text()}`);
  }
  const data = await res.json();
  console.log(JSON.stringify(data, null, 2));
}

main().catch((e) => {
  console.error(e.message || e);
  process.exit(1);
});

#!/usr/bin/env node
/**
 * Verification helper: fetch TokenManager2 events for the last N blocks on BSC.
 * Usage: npx tsx verify-events.ts [blockCount]
 * Default blockCount 50. No private key or tx, read-only.
 */

import { createPublicClient, http, parseAbiItem } from 'viem';
import { bsc } from 'viem/chains';

const TOKEN_MANAGER2_BSC = '0x5c952063c7fc8610FFDB798152D69F0B9550762b' as const;
const EVENTS = [
  parseAbiItem(
    'event TokenCreate(address creator, address token, uint256 requestId, string name, string symbol, uint256 totalSupply, uint256 launchTime, uint256 launchFee)'
  ),
  parseAbiItem(
    'event TokenPurchase(address token, address account, uint256 price, uint256 amount, uint256 cost, uint256 fee, uint256 offers, uint256 funds)'
  ),
  parseAbiItem(
    'event TokenSale(address token, address account, uint256 price, uint256 amount, uint256 cost, uint256 fee, uint256 offers, uint256 funds)'
  ),
  parseAbiItem('event LiquidityAdded(address base, uint256 offers, address quote, uint256 funds)'),
];

function getBscRpcUrl(): string {
  return process.env.BSC_RPC_URL || 'https://bsc-dataseed.binance.org';
}

async function main() {
  const blockCount = parseInt(process.argv[2] ?? '50', 10) || 50;
  const rpcUrl = getBscRpcUrl();
  const client = createPublicClient({
    chain: bsc,
    transport: http(rpcUrl),
  });
  const block = await client.getBlockNumber();
  const fromBlock = block - BigInt(blockCount);
  const toBlock = block;
  const logs = await client.getLogs({
    address: TOKEN_MANAGER2_BSC,
    events: EVENTS,
    fromBlock: fromBlock < 0n ? 0n : fromBlock,
    toBlock,
  });
  console.log(JSON.stringify({ fromBlock: String(fromBlock), toBlock: String(toBlock), count: logs.length, events: logs.map((l) => ({ eventName: l.eventName, blockNumber: Number(l.blockNumber), args: l.args })) }, null, 2));
}

main().catch((e) => {
  console.error(e.message || e);
  process.exit(1);
});
